 540	func resolveTrailReviewComment(ctx context.Context, client *api.Client, trailID, commentID string) (api.TrailReviewComment, error) {
 541		opts := trailReviewListOptions{
 542			Status:           trailReviewStatusAny,
 543			Stale:            trailReviewStaleAny,
 544			IncludeDismissed: true,
 545			Limit:            defaultTrailReviewLimit,
 546		}
 547		var matches []api.TrailReviewComment
 548		for {
 549			comments, hasMore, err := fetchTrailReviewComments(ctx, client, trailID, opts)
 550			if err != nil {
 551				return api.TrailReviewComment{}, err
 552			}
 553			for _, comment := range comments {
 554				if comment.ID == commentID {
 555					return comment, nil
 556				}
 557				if strings.HasPrefix(comment.ID, commentID) {
 558					matches = append(matches, comment)
 559				}
 560			}
 561			if !hasMore {
 562				break
 563			}
 564			opts.Offset += opts.Limit
 565		}
 566		switch len(matches) {
 567		case 0:
 568			return api.TrailReviewComment{}, fmt.Errorf("no review comment %q found", commentID)
 569		case 1:
 570			return matches[0], nil
 571		default:
 572			ids := make([]string, len(matches))
 573			for i := range matches {
 574				ids[i] = matches[i].ID
 575			}
 576			sort.Strings(ids)
 577			return api.TrailReviewComment{}, fmt.Errorf("ambiguous review comment %q (matches: %s)", commentID, strings.Join(ids, ", "))
 578		}
 579	}
