 599	func fetchTrailReviewState(ctx context.Context, client *api.Client, trailID, reviewID string) (api.TrailReviewStateResponse, error) {
 600		var merged api.TrailReviewStateResponse
 601		cursor := ""
 602		seenCursors := map[string]bool{}
 603		for {
 604			resp, err := client.Get(ctx, trailReviewStatePath(trailID, reviewID, cursor))
 605			if err != nil {
 606				return api.TrailReviewStateResponse{}, fmt.Errorf("get review state: %w", err)
 607			}
 608			var page api.TrailReviewStateResponse
 609			decodeErr := func() error {
 610				defer resp.Body.Close()
 611				if err := checkTrailResponse(resp); err != nil {
 612					return err
 613				}
 614				if err := api.DecodeJSON(resp, &page); err != nil {
 615					return fmt.Errorf("decode review state: %w", err)
 616				}
 617				return nil
 618			}()
 619			if decodeErr != nil {
 620				return api.TrailReviewStateResponse{}, decodeErr
 621			}
 622	
 623			if cursor == "" {
 624				merged = page
 625			} else {
 626				merged.Comments = append(merged.Comments, page.Comments...)
 627				merged.NextCursor = page.NextCursor
 628				merged.EventCursor = page.EventCursor
 629			}
 630	
 631			if page.NextCursor == nil || strings.TrimSpace(*page.NextCursor) == "" {
 632				merged.NextCursor = nil
 633				break
 634			}
 635			cursor = strings.TrimSpace(*page.NextCursor)
 636			if seenCursors[cursor] {
 637				return api.TrailReviewStateResponse{}, fmt.Errorf("review state pagination repeated cursor %q", cursor)
 638			}
 639			seenCursors[cursor] = true
 640		}
 641		return merged, nil
 642	}
