 670	func applyTrailReviewSuggestions(ctx context.Context, comment api.TrailReviewComment, checkOnly bool, w io.Writer) (int, error) {
 671		if len(comment.SuggestedChanges) == 0 {
 672			return 0, fmt.Errorf("comment %s has no suggested changes", comment.ID)
 673		}
 674		combinedPatch, supported, err := combinedSafeUnifiedDiffPatch(comment, w)
 675		if err != nil {
 676			return 0, err
 677		}
 678		if supported == 0 {
 679			return 0, fmt.Errorf("comment %s has no supported unified_diff suggested changes", comment.ID)
 680		}
 681		if err := runGitApply(ctx, combinedPatch, true); err != nil {
 682			return 0, fmt.Errorf("suggested changes for comment %s do not apply cleanly: %w", comment.ID, err)
 683		}
 684		if checkOnly {
 685			return supported, nil
 686		}
 687		if err := runGitApply(ctx, combinedPatch, false); err != nil {
 688			return 0, fmt.Errorf("apply suggested changes for comment %s: %w", comment.ID, err)
 689		}
 690		return supported, nil
 691	}
 692	
 693	func combinedSafeUnifiedDiffPatch(comment api.TrailReviewComment, w io.Writer) (string, int, error) {
 694		var combined strings.Builder
 695		supported := 0
 696		for _, change := range comment.SuggestedChanges {
 697			patch := strings.TrimSpace(stringPtrValue(change.Patch))
 698			if change.ChangeType != "unified_diff" || patch == "" {
 699				fmt.Fprintf(w, "Skipping suggested change %s (%s): only unified_diff patches are supported.\n", change.ID, change.ChangeType)
 700				continue
 701			}
 702			if err := validateUnifiedDiffPatchPaths(patch); err != nil {
 703				return "", 0, fmt.Errorf("suggested change %s has unsafe patch path: %w", change.ID, err)
 704			}
 705			if combined.Len() > 0 {
 706				combined.WriteByte('\n')
 707			}
 708			combined.WriteString(patch)
 709			combined.WriteByte('\n')
 710			supported++
 711		}
 712		return combined.String(), supported, nil
 713	}
 714	
 715	func validateUnifiedDiffPatchPaths(patchText string) error {
 716		scanner := bufio.NewScanner(strings.NewReader(patchText))
 717		scanner.Buffer(make([]byte, 0, 64*1024), 1<<20)
 718		for scanner.Scan() {
 719			line := scanner.Text()
 720			for _, p := range patchHeaderPaths(line) {
 721				if err := validatePatchPath(p); err != nil {
 722					return err
 723				}
 724			}
 725		}
 726		if err := scanner.Err(); err != nil {
 727			return fmt.Errorf("scan patch: %w", err)
 728		}
 729		return nil
 730	}
 731	
 732	func patchHeaderPaths(line string) []string {
 733		switch {
 734		case strings.HasPrefix(line, "diff --git "):
 735			fields := strings.Fields(strings.TrimPrefix(line, "diff --git "))
 736			if len(fields) >= 2 {
 737				return []string{fields[0], fields[1]}
 738			}
 739		case strings.HasPrefix(line, "--- ") || strings.HasPrefix(line, "+++ "):
 740			return []string{patchHeaderPath(line[4:])}
 741		case strings.HasPrefix(line, "rename from "):
 742			return []string{strings.TrimSpace(strings.TrimPrefix(line, "rename from "))}
 743		case strings.HasPrefix(line, "rename to "):
 744			return []string{strings.TrimSpace(strings.TrimPrefix(line, "rename to "))}
 745		case strings.HasPrefix(line, "copy from "):
 746			return []string{strings.TrimSpace(strings.TrimPrefix(line, "copy from "))}
 747		case strings.HasPrefix(line, "copy to "):
 748			return []string{strings.TrimSpace(strings.TrimPrefix(line, "copy to "))}
 749		}
 750		return nil
 751	}
 752	
 753	func patchHeaderPath(raw string) string {
 754		raw = strings.TrimSpace(raw)
 755		if beforeTab, _, ok := strings.Cut(raw, "\t"); ok {
 756			raw = beforeTab
 757		}
 758		return raw
 759	}
 760	
 761	func validatePatchPath(raw string) error {
 762		p := strings.TrimSpace(raw)
 763		if p == "" || p == "/dev/null" {
 764			return nil
 765		}
 766		if unquoted, err := strconv.Unquote(p); err == nil {
 767			p = unquoted
 768		}
 769		p = strings.TrimPrefix(p, "a/")
 770		p = strings.TrimPrefix(p, "b/")
 771		p = strings.ReplaceAll(p, "\\", "/")
 772		if strings.HasPrefix(p, "/") {
 773			return fmt.Errorf("absolute path %q is not allowed", raw)
 774		}
 775		clean := path.Clean(p)
 776		if clean == "." || clean == "" {
 777			return nil
 778		}
 779		if clean == ".." || strings.HasPrefix(clean, "../") {
 780			return fmt.Errorf("path %q escapes the repository", raw)
 780			return fmt.Errorf("path %q escapes the repository", raw)
 781		}
 782		for _, part := range strings.Split(clean, "/") {
 783			if part == ".git" {
 784				return fmt.Errorf("path %q targets .git metadata", raw)
 785			}
 786		}
 787		return nil
 788	}
