 790	func runGitApply(ctx context.Context, patch string, checkOnly bool) error {
 791		root, err := paths.WorktreeRoot(ctx)
 792		if err != nil {
 793			return fmt.Errorf("resolve worktree root: %w", err)
 794		}
 795		args := []string{"-C", root, "apply"}
 796		if checkOnly {
 797			args = append(args, "--check")
 798		}
 799		cmd := exec.CommandContext(ctx, "git", args...)
 800		cmd.Stdin = bytes.NewBufferString(patch + "\n")
 801		out, err := cmd.CombinedOutput()
 802		if err != nil {
 803			msg := strings.TrimSpace(string(out))
 804			if msg != "" {
 805				return fmt.Errorf("git apply: %w: %s", err, msg)
 806			}
 807			return fmt.Errorf("git apply: %w", err)
 808		}
 809		return nil
 810	}
