 860	func buildTrailReviewStartRequest(ctx context.Context, target trailReviewTarget, opts trailReviewStartOptions) (api.TrailReviewStartRequest, error) {
 861		baseRef := strings.TrimSpace(opts.BaseRef)
 862		if baseRef == "" {
 863			baseRef = target.Trail.Base
 864		}
 865		headRef := strings.TrimSpace(opts.HeadRef)
 866		if headRef == "" {
 867			if branch, err := GetCurrentBranch(ctx); err == nil {
 868				headRef = branch
 869			}
 870		}
 871		headSHA := strings.TrimSpace(opts.HeadSHA)
 872		if headSHA == "" {
 873			sha, err := resolveGitRev(ctx, "HEAD")
 874			if err != nil {
 875				return api.TrailReviewStartRequest{}, err
 876			}
 877			headSHA = sha
 878		}
 879		baseSHA := strings.TrimSpace(opts.BaseSHA)
 880		if baseSHA == "" && baseRef != "" {
 881			if sha, err := resolveGitRev(ctx, baseRef); err == nil {
 882				baseSHA = sha
 883			}
 884		}
 885		return api.TrailReviewStartRequest{
 886			HeadSHA: optionalStringPtr(headSHA),
 887			BaseSHA: optionalStringPtr(baseSHA),
 888			BaseRef: optionalStringPtr(baseRef),
 889			HeadRef: optionalStringPtr(headRef),
 890		}, nil
 891	}
 892	
 893	func resolveGitRev(ctx context.Context, ref string) (string, error) {
 894		root, err := paths.WorktreeRoot(ctx)
 895		if err != nil {
 896			return "", fmt.Errorf("resolve worktree root: %w", err)
 897		}
 898		cmd := exec.CommandContext(ctx, "git", "-C", root, "rev-parse", ref)
 899		out, err := cmd.Output()
 900		if err != nil {
 901			return "", fmt.Errorf("git rev-parse %s: %w", ref, err)
 902		}
 903		sha := strings.TrimSpace(string(out))
 904		if sha == "" {
 905			return "", fmt.Errorf("git rev-parse %s: empty output", ref)
 906		}
 907		return sha, nil
 908	}
