func filterTrailResourcesByStatuses(trails []api.TrailResource, statuses []trail.Status) []api.TrailResource {
	if len(statuses) == 0 {
		return trails
	}
	statusSet := make(map[string]bool, len(statuses))
	for _, status := range statuses {
		statusSet[string(status)] = true
	}
	filtered := make([]api.TrailResource, 0, len(trails))
	for _, t := range trails {
		if statusSet[t.Status] {
			filtered = append(filtered, t)
		}
	}
	return filtered
}

