func printTrailReviewTrailList(w io.Writer, trails []api.TrailResource) {
	if len(trails) == 0 {
		fmt.Fprintln(w, "No trails found.")
		fmt.Fprintln(w)
		fmt.Fprintln(w, "Create a trail for the current branch with:")
		fmt.Fprintln(w, "  entire trail create")
		return
	}
	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "NUM\tID\tSTATUS\tBRANCH\tTITLE\tUPDATED")
	for _, t := range trails {
		number := "-"
		if t.Number > 0 {
			number = strconv.Itoa(t.Number)
		}
		fmt.Fprintf(tw, "%s\t%s\t%s\t%s\t%s\t%s\n", number, abbreviate12(t.ID), t.Status, t.Branch, truncateOneLine(t.Title, 60), timeAgo(t.UpdatedAt))
	}
	_ = tw.Flush()
	fmt.Fprintln(w)
	fmt.Fprintln(w, "Use 'entire trail review <num>' to inspect a trail, or omit <num> to use the current branch's trail.")
}

