func runTrailReviewList(cmd *cobra.Command, opts trailReviewTrailListOptions) error {
	if opts.Limit <= 0 {
		return errors.New("limit must be greater than 0")
	}
	statusFilters, err := parseTrailStatusFilter(opts.Status)
	if err != nil {
		return err
	}
	client, err := NewAuthenticatedAPIClient(cmd.Context(), trailInsecureHTTP(cmd))
	if err != nil {
		return fmt.Errorf("authentication required: %w", err)
	}
	host, owner, repo, err := gitremote.ResolveRemoteRepo(cmd.Context(), "origin")
	if err != nil {
		return fmt.Errorf("failed to resolve repository: %w", err)
	}
	trails, err := fetchTrailReviewTrails(cmd.Context(), client, host, owner, repo)
	if err != nil {
		return err
	}
	trails = filterTrailResourcesByStatuses(trails, statusFilters)
	sort.Slice(trails, func(i, j int) bool {
		return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
	})
	trails = limitTrailResources(trails, opts.Limit)
	if opts.JSON {
		enc := json.NewEncoder(cmd.OutOrStdout())
		enc.SetIndent("", "  ")
		if err := enc.Encode(trails); err != nil {
			return fmt.Errorf("encode trail review list: %w", err)
		}
		return nil
	}
	printTrailReviewTrailList(cmd.OutOrStdout(), trails)
	return nil
}

func runTrailReviewDashboard(cmd *cobra.Command, selector string, opts trailReviewListOptions) error {
	client, target, err := authenticatedTrailReviewTarget(cmd, selector)
	if err != nil {
		return err
	}
	comments, hasMore, err := fetchTrailReviewComments(cmd.Context(), client, target.Trail.ID, opts)
	if err != nil {
		return err
	}
	summaryComments, err := fetchAllTrailReviewComments(cmd.Context(), client, target.Trail.ID, trailReviewSummaryOptions())
	if err != nil {
		return err
	}
	counts := countTrailReviewComments(summaryComments)
	if opts.JSON {
		return encodeTrailReviewJSON(cmd.OutOrStdout(), target, comments, hasMore, counts)
	}
	printTrailReviewDashboard(cmd.OutOrStdout(), target, comments, hasMore, opts, counts)
	return nil
}

func runTrailReviewComments(cmd *cobra.Command, selector string, opts trailReviewListOptions) error {
	client, target, err := authenticatedTrailReviewTarget(cmd, selector)
	if err != nil {
		return err
	}
	comments, hasMore, err := fetchTrailReviewComments(cmd.Context(), client, target.Trail.ID, opts)
	if err != nil {
