	}
	if opts.JSON {
		return encodeTrailReviewJSON(cmd.OutOrStdout(), target, comments, hasMore, countTrailReviewComments(comments))
	}
	printTrailReviewComments(cmd.OutOrStdout(), comments, hasMore)
	return nil
}

