// The mise test:e2e tasks set this automatically via `mise run build`.
func BinPath() string {
	p := os.Getenv("E2E_ENTIRE_BIN")
	if p == "" {
		log.Fatal("entire: E2E_ENTIRE_BIN not set — run tests via `mise run test:e2e`")
	}
	return p
}

// RewindPoint represents a single entry from `entire rewind --list`.
type RewindPoint struct {
	ID               string `json:"id"`
	Message          string `json:"message"`
	MetadataDir      string `json:"metadata_dir"`
	Date             string `json:"date"`
	IsTaskCheckpoint bool   `json:"is_task_checkpoint"`
	ToolUseID        string `json:"tool_use_id"`
	IsLogsOnly       bool   `json:"is_logs_only"`
	CondensationID   string `json:"condensation_id"`
	SessionID        string `json:"session_id"`
}

// Enable runs `entire enable` for the given agent with telemetry disabled.
func Enable(t *testing.T, dir, agent string) {
	t.Helper()
	run(t, dir, "enable", "--agent", agent, "--telemetry=false")
}

// Disable runs `entire disable` in the given directory.
func Disable(t *testing.T, dir string) {
	t.Helper()
	run(t, dir, "disable")
}

// Doctor runs `entire doctor --force` and returns the output.
func Doctor(t *testing.T, dir string) string {
	t.Helper()
	return run(t, dir, "doctor", "--force")
}

// CleanDryRun runs `entire clean --dry-run` and returns the output.
func CleanDryRun(t *testing.T, dir string) string {
	t.Helper()
	return run(t, dir, "clean", "--dry-run")
}

// CleanForce runs `entire clean --force` and returns the output.
func CleanForce(t *testing.T, dir string) string {
	t.Helper()
	return run(t, dir, "clean", "--force")
}

// RewindList runs `entire rewind --list` and parses the JSON output.
func RewindList(t *testing.T, dir string) []RewindPoint {
	t.Helper()
	out := run(t, dir, "checkpoint", "rewind", "--list")

	var points []RewindPoint
	if err := json.Unmarshal([]byte(out), &points); err != nil {
		t.Fatalf("parse rewind list: %v\nraw output: %s", err, out)
	}
	return points
}

// Rewind runs `entire rewind --to <id>`. Returns an error instead of
// failing the test, since callers may test failure cases.
func Rewind(t *testing.T, dir, id string) error {
	t.Helper()
	return runErr(dir, "checkpoint", "rewind", "--to", id)
}

// RewindLogsOnly runs `entire rewind --to <id> --logs-only`.
func RewindLogsOnly(t *testing.T, dir, id string) error {
	t.Helper()
	return runErr(dir, "checkpoint", "rewind", "--to", id, "--logs-only")
}

// run executes an `entire` subcommand in dir and fails the test on error.
func run(t *testing.T, dir string, args ...string) string {
	t.Helper()
	cmd := execx.NonInteractive(context.Background(), BinPath(), args...)
	cmd.Dir = dir
	cmd.Env = os.Environ()

	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("entire %s failed: %v\n%s", strings.Join(args, " "), err, out)
	}
	return strings.TrimSpace(string(out))
}

// runErr executes an `entire` subcommand in dir and returns any error.
func runErr(dir string, args ...string) error {
	cmd := execx.NonInteractive(context.Background(), BinPath(), args...)
	cmd.Dir = dir
	cmd.Env = os.Environ()

	out, err := cmd.CombinedOutput()
	if err != nil {
		return &ExecError{
			Args:   args,
			Err:    err,
			Output: string(out),
		}
	}
	return nil
}

// ExecError wraps an entire CLI execution failure with its output.
type ExecError struct {
	Args   []string
	Err    error
	Output string
}

func (e *ExecError) Error() string {
	return "entire " + strings.Join(e.Args, " ") + ": " + e.Err.Error() + "\n" + e.Output
}

func (e *ExecError) Unwrap() error {
	return e.Err
}

// Explain runs `entire explain --checkpoint <id>` and returns the output.
func Explain(t *testing.T, dir, checkpointID string) string {
	t.Helper()
	return run(t, dir, "checkpoint", "explain", "--checkpoint", checkpointID)
}

// ExplainGenerate runs `entire explain --checkpoint <id> --generate`.
// Returns (output, error) — doesn't fail test since callers may test failure cases.
func ExplainGenerate(dir, checkpointID string) (string, error) {
	return runOutput(dir, "checkpoint", "explain", "--checkpoint", checkpointID, "--generate")
}

// ExplainCommit runs `entire explain --commit <ref>`.
// Returns (output, error) — for testing failure cases.
func ExplainCommit(dir, ref string) (string, error) {
	return runOutput(dir, "checkpoint", "explain", "--commit", ref)
}

// AttachWithEnv runs `entire attach <session-id> --agent <agent> --force`
// with extra env vars.
func AttachWithEnv(dir string, extraEnv []string, sessionID, agent string) (string, error) {
	return runOutputEnv(dir, extraEnv, "session", "attach", sessionID, "--agent", agent, "--force")
}

// Resume runs `entire resume <branch> --force` and returns the output.
func Resume(dir, branch string) (string, error) {
	return runOutput(dir, "session", "resume", branch, "--force")
}

// ResumeWithEnv runs `entire resume <branch> --force` with extra env vars.
func ResumeWithEnv(dir, branch string, extraEnv []string) (string, error) {
	return runOutputEnv(dir, extraEnv, "session", "resume", branch, "--force")
}

// runOutput executes an `entire` subcommand and returns (output, error).
func runOutput(dir string, args ...string) (string, error) {
	return runOutputEnv(dir, nil, args...)
}

func runOutputEnv(dir string, extraEnv []string, args ...string) (string, error) {
	cmd := execx.NonInteractive(context.Background(), BinPath(), args...)
	cmd.Dir = dir
	cmd.Env = append(append([]string{}, os.Environ()...), extraEnv...)

	out, err := cmd.CombinedOutput()
	if err != nil {
		return string(out), &ExecError{
			Args:   args,
			Err:    err,
			Output: string(out),
		}
	}
	return strings.TrimSpace(string(out)), nil
}

//go:build e2e

package tests

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"testing"

	"github.com/entireio/cli/e2e/agents"
	"github.com/entireio/cli/e2e/entire"
	"github.com/entireio/cli/e2e/testutil"
)

func TestMain(m *testing.M) {
	runDir := os.Getenv("E2E_ARTIFACT_DIR")
	if runDir == "" {
		_, file, _, _ := runtime.Caller(0)
		testutil.ArtifactRoot = filepath.Join(filepath.Dir(file), "..", "artifacts")
		runDir = testutil.ArtifactRunDir()
	}
	_ = os.MkdirAll(runDir, 0o755)
	testutil.SetRunDir(runDir)

	// Resolve the entire binary (set by mise run build via E2E_ENTIRE_BIN).
	entireBin := entire.BinPath()
	if err := ensureHookEntireBinary(entireBin); err != nil {
		fmt.Fprintf(os.Stderr, "preflight: prepare hook entire binary: %v\n", err)
		os.Exit(1)
	}

	// Prepend the binary's directory to PATH so that git hooks and agent
	// hooks (which call bare "entire") resolve to the same binary the test
	// harness uses, not a system-installed one.
	os.Setenv("PATH", filepath.Dir(entireBin)+string(os.PathListSeparator)+os.Getenv("PATH"))

	// Preflight: verify required dependencies before running any tests.
	// tmux is only required on Unix (interactive session tests are skipped on Windows).
	var missing []string
	requiredBins := []string{"git"}
	if runtime.GOOS != "windows" {
		requiredBins = append(requiredBins, "tmux")
	}
	for _, bin := range requiredBins {
		if _, err := exec.LookPath(bin); err != nil {
			missing = append(missing, bin)
		}
	}
	for _, a := range agents.All() {
		if _, err := exec.LookPath(a.Binary()); err != nil {
			missing = append(missing, fmt.Sprintf("%s (%s)", a.Binary(), a.Name()))
		}
	}
	if len(missing) > 0 {
		fmt.Fprintf(os.Stderr, "preflight: missing required binaries: %v\n", missing)
		os.Exit(1)
	}

	version := "unknown"
	if out, err := exec.Command(entireBin, "version").Output(); err == nil {
		version = string(out)
	}

	// Write preflight info to artifact dir only — gotestsum swallows both
	// stdout and stderr, so the test-e2e script cats this file at the end.
	preflight := fmt.Sprintf("entire binary:  %s\nentire version: %s\n",
		entireBin, version)
	_ = os.WriteFile(filepath.Join(runDir, "entire-version.txt"), []byte(preflight), 0o644)

	// Don't look at user's Git config, ignore everything except the project-local Git settings.
	// This avoids oddball configs in ~/.gitconfig messing with our E2E tests.
	// We use an empty temp file instead of os.DevNull because git on Windows
	// cannot open NUL as a config file ("unable to access 'NUL': Invalid argument").
	emptyConfig := filepath.Join(runDir, "empty-gitconfig")
	_ = os.WriteFile(emptyConfig, nil, 0o644)
	os.Setenv("GIT_CONFIG_GLOBAL", emptyConfig)

	os.Exit(m.Run())
}

func ensureHookEntireBinary(entireBin string) error {
	dir := filepath.Dir(entireBin)
	hookName := "entire"
	if runtime.GOOS == "windows" {
		hookName = "entire.exe"
	}
	hookBin := filepath.Join(dir, hookName)
	if filepath.Clean(entireBin) == filepath.Clean(hookBin) {
		return nil
	}

	_ = os.Remove(hookBin)

	if runtime.GOOS == "windows" {
		data, err := os.ReadFile(entireBin)
		if err != nil {
			return err
		}
		return os.WriteFile(hookBin, data, 0o755)
	}

	return os.Symlink(entireBin, hookBin)
}

package cli

import (
	"context"
	"errors"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
)

// NewAuthenticatedAPIClient creates an API client targeting api.BaseURL()
// (the data API origin) carrying a token valid for that audience.
//
// Resolution: looks up the core token from the keyring, then either uses
// it directly (single-host setup, or when the core token's `aud` already
// covers api.BaseURL()) or performs an RFC 8693 token exchange against
// the auth host to obtain a token scoped to the data API. Exchanged
// tokens are cached in-memory keyed off the wire-affecting fields of
// the request — see tokenmanager.cacheKey for the precise key shape.
//
// Pass insecureHTTP=true to allow plain HTTP base URLs for local
// development. Both api.BaseURL() and api.AuthBaseURL() are validated:
// the bearer travels to the data host on resource requests, and the
// core token travels to the auth host during the exchange step.
func NewAuthenticatedAPIClient(ctx context.Context, insecureHTTP bool) (*api.Client, error) {
	dataURL, authURL := api.BaseURL(), api.AuthBaseURL()
	if insecureHTTP {
		auth.EnableInsecureHTTP()
	} else {
		if err := api.RequireSecureURL(dataURL); err != nil {
			return nil, fmt.Errorf("base URL check: %w", err)
		}
		if authURL != dataURL {
			if err := api.RequireSecureURL(authURL); err != nil {
				return nil, fmt.Errorf("auth base URL check: %w", err)
			}
		}
	}

	// tokenmanager validates Resource as a strict origin URL; strip any path
	// the operator may have included in ENTIRE_API_BASE_URL before handing
	// it across the package boundary.
	token, err := auth.TokenForResource(ctx, api.OriginOnly(dataURL))
	if err != nil {
		if errors.Is(err, auth.ErrNotLoggedIn) {
			return nil, errors.New("not logged in (run 'entire login' first)")
		}
		return nil, fmt.Errorf("resolve API token: %w", err)
	}

	return api.NewClient(token), nil
}

package auth

import (
	"errors"
	"fmt"
	"strings"

	"github.com/entireio/auth-go/tokens"
	"github.com/entireio/auth-go/tokenstore"
	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/zalando/go-keyring"
)

// keyringService is the OS-keyring service name for this CLI. Renaming
// would orphan every existing user's stored credentials — they'd appear
// logged out until they ran `entire login` again. Don't change this
// without a migration path.
const keyringService = "entire-cli"

// Store manages CLI authentication tokens via a pluggable backend. The
// production binary always resolves to the OS keyring. A file-backed
// backend is available only in builds tagged `authfilestore` (used by
// integration tests to avoid the OS keychain).
//
// Implements tokenstore.Store so it can be passed to tokenmanager.New
// as the persistence layer. The interface methods (SaveTokens /
// LoadTokens / DeleteTokens) delegate to the same backend as the
// legacy SaveToken / GetToken / DeleteToken pair, so production and
// test paths share a single source of truth.
type Store struct {
	service string
	backend tokenBackend
}

// tokenBackend abstracts token persistence. Implementations must treat
// "missing key" as a non-error: get returns ("", nil) and delete is a
// no-op so callers don't have to plumb backend-specific sentinels.
type tokenBackend interface {
	save(service, key, value string) error
	get(service, key string) (string, error)
	delete(service, key string) error
}

// chooseBackend returns the backend used by NewStore and
// NewStoreWithService. The default returns the keyring backend; the
// `authfilestore` build adds an init() that may swap in a file-backed
// backend when the test env var is set.
var chooseBackend = func() tokenBackend { return keyringBackend{} }

// NewStore returns a Store backed by the system keyring (or, in
// `authfilestore` builds, optionally a file-backed test store).
func NewStore() *Store {
	return &Store{service: keyringService, backend: chooseBackend()}
}

// NewStoreWithService returns a Store with a custom keyring service name (for testing).
// Honors the same backend selection as NewStore so tests that opt into the
// file-backed test store via env var see consistent behavior across both
// constructors.
func NewStoreWithService(service string) *Store {
	return &Store{service: service, backend: chooseBackend()}
}

// SaveToken persists an access token for the given base URL. Prefer
// SaveTokens (the tokenstore.Store interface method) for new callers;
// SaveToken is kept for the legacy direct-bearer call sites (login,
// logout, auth status/list/revoke) that don't go through the tokenmanager.
func (s *Store) SaveToken(baseURL, token string) error {
	token = strings.TrimSpace(token)
	if token == "" {
		return errors.New("refusing to save empty token")
	}
	return s.backend.save(s.service, baseURL, token)
}

// GetToken retrieves a stored token for the given base URL. Returns
// an empty string (and no error) if no token is stored, or if the
// stored value is JSON-shaped (defensive: pre-shim entries are
// opaque token strings, never JSON; a JSON blob in the keyring is
// corruption and must not be put on the wire as a bearer).
//
// Prefer LoadTokens (the tokenstore.Store interface method) for new
// callers — it returns the full TokenSet so refresh tokens and expiry
// survive the round trip. GetToken is retained for the direct-bearer
// call sites that only need the access token string.
func (s *Store) GetToken(baseURL string) (string, error) {
	raw, err := s.backend.get(s.service, baseURL)
	if err != nil {
		return "", err
	}
	if looksJSONShaped(raw) {
		return "", nil
	}
	return raw, nil
}

// looksJSONShaped reports whether the keyring value's first
// non-whitespace byte is '{' or '['. Used to reject corrupt /
// previous-encoding entries before they end up in an
// Authorization: Bearer header.
func looksJSONShaped(s string) bool {
	trimmed := strings.TrimLeft(s, " \t\r\n")
	if trimmed == "" {
		return false
	}
	return trimmed[0] == '{' || trimmed[0] == '['
}

// DeleteToken removes a stored token for the given base URL. Returns
// no error if the token does not exist. Prefer DeleteTokens (the
// tokenstore.Store interface method); DeleteToken is retained for
// direct-bearer call sites.
func (s *Store) DeleteToken(baseURL string) error {
	return s.backend.delete(s.service, baseURL)
}

// SaveTokens implements tokenstore.Store. Refresh token, scope, expiry,
// and token type are intentionally dropped — the entire device-flow
// surface doesn't issue refresh tokens, and the legacy keyring/file
// layout stores bare access-token strings. If refresh-token support
// lands, this method (and the tokenBackend interface) become the
// migration point.
func (s *Store) SaveTokens(profile string, t tokens.TokenSet) error {
	access := strings.TrimSpace(t.AccessToken)
	if access == "" {
		return errors.New("refusing to save empty access token")
	}
	return s.backend.save(s.service, profile, access)
}

// LoadTokens implements tokenstore.Store. Reads the bare-string entry
// and wraps it back into a TokenSet. Returns tokenstore.ErrNotFound
// when nothing is stored under the profile (or the stored value is
// JSON-shaped — see GetToken's note about defensive rejection of
// non-token blobs) so callers can errors.Is against the lib sentinel.
func (s *Store) LoadTokens(profile string) (tokens.TokenSet, error) {
	access, err := s.backend.get(s.service, profile)
	if err != nil {
		return tokens.TokenSet{}, err
	}
	if access == "" || looksJSONShaped(access) {
		return tokens.TokenSet{}, tokenstore.ErrNotFound
	}
	return tokens.TokenSet{AccessToken: access}, nil
}

// DeleteTokens implements tokenstore.Store.
func (s *Store) DeleteTokens(profile string) error {
	return s.backend.delete(s.service, profile)
}

// LookupCurrentToken retrieves the token for the current auth base URL.
// Tokens are keyed by the auth issuer (api.AuthBaseURL()) since that's the
// host that minted them; in single-host deployments AuthBaseURL falls back
// to BaseURL so behaviour is unchanged.
func LookupCurrentToken() (string, error) {
	return NewStore().GetToken(api.AuthBaseURL())
}

type keyringBackend struct{}

func (keyringBackend) save(service, key, value string) error {
	if err := keyring.Set(service, key, value); err != nil {
		return fmt.Errorf("save token to keyring: %w", err)
	}
	return nil
}

func (keyringBackend) get(service, key string) (string, error) {
	token, err := keyring.Get(service, key)
	if errors.Is(err, keyring.ErrNotFound) {
		return "", nil
	}
	if err != nil {
		return "", fmt.Errorf("get token from keyring: %w", err)
	}
	return token, nil
}

func (keyringBackend) delete(service, key string) error {
	err := keyring.Delete(service, key)
	if errors.Is(err, keyring.ErrNotFound) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("delete token from keyring: %w", err)
	}
	return nil
}

