func newTrailReviewListCmd() *cobra.Command {
	opts := trailReviewTrailListOptions{
		Status: trailListStatusAny,
		Limit:  defaultTrailReviewLimit,
	}
	cmd := &cobra.Command{
		Use:   "list",
		Short: "List trails that can be reviewed in this repo",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runTrailReviewList(cmd, opts)
		},
	}
	cmd.Flags().StringVar(&opts.Status, "status", opts.Status, "Filter by comma-separated trail status(es); use 'any' for all")
	cmd.Flags().IntVarP(&opts.Limit, "limit", "n", opts.Limit, "Maximum number of trails to show")
	cmd.Flags().BoolVar(&opts.JSON, "json", false, "Output as JSON")
	return cmd
}

func runTrailReviewList(cmd *cobra.Command, opts trailReviewTrailListOptions) error {
	if opts.Limit <= 0 {
		return errors.New("limit must be greater than 0")
	}
	statusFilters, err := parseTrailStatusFilter(opts.Status)
	if err != nil {
		return err
	}
	client, err := NewAuthenticatedAPIClient(cmd.Context(), trailInsecureHTTP(cmd))
	if err != nil {
		return fmt.Errorf("authentication required: %w", err)
	}
	host, owner, repo, err := gitremote.ResolveRemoteRepo(cmd.Context(), "origin")
	if err != nil {
		return fmt.Errorf("failed to resolve repository: %w", err)
	}
	trails, err := fetchTrailReviewTrails(cmd.Context(), client, host, owner, repo)
	if err != nil {
		return err
	}
	trails = filterTrailResourcesByStatuses(trails, statusFilters)
	sort.Slice(trails, func(i, j int) bool {
		return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
	})
	trails = limitTrailResources(trails, opts.Limit)
	if opts.JSON {
		enc := json.NewEncoder(cmd.OutOrStdout())
		enc.SetIndent("", "  ")
		if err := enc.Encode(trails); err != nil {
			return fmt.Errorf("encode trail review list: %w", err)
		}
		return nil
	}
	printTrailReviewTrailList(cmd.OutOrStdout(), trails)
	return nil
}

