func fetchTrailReviewTrails(ctx context.Context, client *api.Client, host, owner, repo string) ([]api.TrailResource, error) {
	resp, err := client.Get(ctx, trailsBasePath(host, owner, repo))
	if err != nil {
		return nil, fmt.Errorf("list trails: %w", err)
	}
	defer resp.Body.Close()
	if err := checkTrailResponse(resp); err != nil {
		return nil, err
	}
	var listResp api.TrailListResponse
	if err := api.DecodeJSON(resp, &listResp); err != nil {
		return nil, fmt.Errorf("decode trail list: %w", err)
	}
	return listResp.Trails, nil
}

func filterTrailResourcesByStatuses(trails []api.TrailResource, statuses []trail.Status) []api.TrailResource {
	if len(statuses) == 0 {
		return trails
	}
	statusSet := make(map[string]bool, len(statuses))
	for _, status := range statuses {
		statusSet[string(status)] = true
	}
	filtered := make([]api.TrailResource, 0, len(trails))
	for _, t := range trails {
		if statusSet[t.Status] {
			filtered = append(filtered, t)
		}
	}
	return filtered
}

func limitTrailResources(trails []api.TrailResource, limit int) []api.TrailResource {
	if len(trails) <= limit {
		return trails
	}
	return trails[:limit]
}

