	if opts.Severity != "" {
		q.Set("severity", opts.Severity)
	}
	if opts.Stale != "" && opts.Stale != trailReviewStaleAny {
		q.Set("stale", opts.Stale)
	}
	if opts.IncludeDismissed {
		q.Set("include_dismissed", "true")
	}
	if opts.Limit > 0 {
