	var stdout, stderr bytes.Buffer
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	reason, lastID, err := streamOnce(ctx, client, "/stream", "", false, false, &stdout, &stderr)
	if err != nil {
		t.Fatalf("streamOnce error: %v", err)
