 	cmd := exec.CommandContext(ctx, "git", args...)
 	cmd.Stdin = bytes.NewBufferString(patch + "\n")
 	out, err := cmd.CombinedOutput()
 	if err != nil {
 		msg := strings.TrimSpace(string(out))
 		if msg != "" {
 			return fmt.Errorf("git apply: %w: %s", err, msg)
